# Reproduce every number in the proof. Needs only pandas and a prices.csv (Date, one column per ticker).
# Usage: python proof_script.py [path/to/prices.csv]
import json
import sys

def portfolio_value(prices, weights):
    """Value of 1 dollar kept at fixed weights, rebalanced daily, from the first day all funds exist."""
    prices = prices[list(weights)].dropna()
    returns = prices.pct_change().fillna(0.0)
    return (1 + returns @ pd.Series(weights)).cumprod()


def cagr(values):
    """Compound yearly growth rate."""
    years = (values.index[-1] - values.index[0]).days / 365.25
    return float((values.iloc[-1] / values.iloc[0]) ** (1 / years) - 1)


def volatility(returns):
    """Yearly size of the ups and downs (std of daily returns x sqrt(252))."""
    return float(returns.std() * 252 ** 0.5)


def max_drawdown(values):
    """Worst fall from a previous peak (a negative number)."""
    peak = values.cummax()
    return float((values / peak - 1).min())


def sharpe(returns, rf=0.0):
    """Return per unit of risk (annualised, risk-free rate rf per year)."""
    return float((returns.mean() - rf / 252) / returns.std() * 252 ** 0.5)


def window_return(values, start, end):
    """Total change of the portfolio between two dates (a stress window)."""
    w = values.loc[start:end]
    return float(w.iloc[-1] / w.iloc[0] - 1)


def overlap(weights, sector_weights):
    """Share of the portfolio in the sector your job already depends on.

    sector_weights maps ticker -> fraction of that fund in the sector."""
    return float(sum(w * sector_weights.get(t, 0.0) for t, w in weights.items()))

import pandas as pd  # noqa: E402

STRATEGY = {"SHY": 0.3, "VTI": 0.22, "VXUS": 0.18, "XLV": 0.15, "BND": 0.15}
BASELINE = {"QQQ": 1.0}
LAST_DAY = "2022-01-02"  # day before the simulation date: nothing later is used
WINDOWS = [["2015-16 sell-off", "2015-07-20", "2016-02-11"], ["Q4 2018 sell-off", "2018-10-01", "2018-12-24"], ["COVID crash", "2020-02-19", "2020-03-23"]]
OVERLAP = (0.31, 0.52)  # from the portfolio engine's sector data

prices = pd.read_csv(sys.argv[1] if len(sys.argv) > 1 else "prices.csv", index_col=0, parse_dates=True)
prices = prices.sort_index().loc["2015-01-01":LAST_DAY, sorted(set(STRATEGY) | set(BASELINE))].dropna()
out = {}
for name, w in (("strategy", STRATEGY), ("baseline", BASELINE)):
    v = portfolio_value(prices, w)
    r = v.pct_change().dropna()
    out[name] = {"cagr": round(cagr(v), 3), "volatility": round(volatility(r), 3),
                 "max_drawdown": round(max_drawdown(v), 3), "sharpe": round(sharpe(r), 2), "_v": v}
stress = []
for name, a, b in WINDOWS:
    last = out["strategy"]["_v"].index
    if pd.Timestamp(a) < last[0] or pd.Timestamp(a) >= last[-1]:
        continue
    b = min(b, str(last[-1].date()))
    stress.append({"name": name, "from": a, "to": b,
                   **{k: round(window_return(out[k]["_v"], a, b), 3) for k in ("strategy", "baseline")}})
for k in out:
    del out[k]["_v"]
out["tech_overlap"] = dict(zip(("strategy", "baseline"), OVERLAP))
out["stress"] = stress
print(json.dumps(out, indent=2))
